from sympy.ntheory.modular import solve_congruence

def solve(inputs: dict) -> float:
    moduli = inputs['MODULI']
    remainders = inputs['REMAINDERS']
    solution, _ = solve_congruence(*zip(remainders, moduli))
    return float(solution)

